/* Mosswood — the seed catalogue, the garden basket & the Ghibli shelf */

function plant() { plantModal(); }

function seedCard(def) {
  const seeds = game.inventory.Seeds || 0;
  const free = 24 - game.plants.length;
  const can = seeds > 0 && free > 0;
  const catName = def.cat === 'herb' ? 'HERB' : def.cat === 'veg' ? 'VEGGIE' : 'FRUIT';
  return `<button class="seed-card" data-plant="${def.id}" ${can ? '' : 'disabled'}>
    <span class="seed-art" style="--leaf:${def.leaf};--leaf2:${def.leaf2};--accent:${def.accent}"><b>${def.emoji}</b><i></i><i></i><i></i></span>
    <span class="seed-copy"><b>${def.name}</b><small>${catName} · ${def.grow} day${def.grow === 1 ? '' : 's'} · +${def.yield}</small><em>${def.blurb}</em></span>
    <span class="seed-price">${seeds > 0 ? '1 seed' : 'need seeds'}</span>
  </button>`;
}

function plantModal() {
  const free = 24 - game.plants.length;
  if (free <= 0) {
    toast('Every bed is full. Harvest something before planting more 🌱');
    return;
  }
  const body = `<div class="seed-tabs" id="seedTabs">
      <button class="active" data-cat="all">All 23</button>
      <button data-cat="herb">Herbs</button>
      <button data-cat="veg">Veggies</button>
      <button data-cat="fruit">Fruit</button>
      <span class="seed-status">${free} spots free · ${game.inventory.Seeds || 0} seeds</span>
    </div>
    <div class="seed-grid" id="seedGrid">${PLANTS.map(seedCard).join('')}</div>
    <div class="modal-note">Each planting uses one seed. Herbs are quick; melons and pumpkins take a little longer. Rain helps.</div>`;
  shellModal({
    eyebrow: 'THE KITCHEN GARDEN · 23 THINGS TO GROW',
    title: 'What shall we grow?',
    desc: 'Mint and basil for the kitchen, catnip for your companion, and enough veggies and fruit to fill a whole summer.',
    body,
    foot: 'Plant · water · wait for a sunny morning.',
    wide: true
  });
  const grid = $('#seedGrid');
  const draw = cat => { grid.innerHTML = PLANTS.filter(d => cat === 'all' || d.cat === cat).map(seedCard).join(''); bind(); };
  const bind = () => {
    $$('#seedGrid .seed-card').forEach(btn => {
      btn.onclick = () => {
        if (btn.disabled) return;
        const def = PLANTS.find(d => d.id === btn.dataset.plant);
        if (!def) return;
        if ((game.inventory.Seeds || 0) < 1) return toast('You are out of seeds. Fern & Fable has seed tins.');
        if (game.plants.length >= 24) return toast('Every bed is full right now.');
        game.inventory.Seeds--;
        game.plants.push({ id: def.id, planted: game.day, ready: game.day + def.grow, slot: game.plants.length });
        complete('garden');
        toast(`${def.name} planted. ${def.grow} day${def.grow === 1 ? '' : 's'} of quiet growing.`);
        closeModal();
        save();
      };
    });
  };
  $$('#seedTabs button').forEach(b => {
    b.onclick = () => {
      $$('#seedTabs button').forEach(x => x.classList.toggle('active', x === b));
      draw(b.dataset.cat);
    };
  });
  bind();
}

function harvest() {
  const ready = readyPlants();
  if (!ready.length) {
    toast(game.plants.length ? 'Not quite ready yet. Give them a little more time 🌱' : 'Nothing to pick just yet. Try planting seeds!');
    return;
  }
  const rows = ready.map(p => {
    const def = plantDef(p);
    return `<div class="harvest-row"><span>${def.emoji}</span><b>${def.name}</b><small>+${def.yield} ${def.cat === 'herb' ? 'bundle' + (def.yield === 1 ? '' : 's') : 'harvest'}</small></div>`;
  }).join('');
  shellModal({
    eyebrow: 'THE GARDEN BASKET',
    title: 'A lovely little harvest',
    desc: `${ready.length} plant${ready.length === 1 ? ' is' : 's are'} ready. Bring them in while the light is good.`,
    body: `<div class="harvest-list">${rows}</div><button class="ritual-button" id="harvestAll">Gather everything 🧺</button>`,
    foot: 'Harvesting uses 1 energy.',
    wide: ready.length > 8
  });
  $('#harvestAll').onclick = () => {
    if (!spend()) return;
    const counts = {};
    ready.forEach(p => {
      const def = plantDef(p);
      game.inventory[def.name] = (game.inventory[def.name] || 0) + def.yield;
      counts[def.name] = (counts[def.name] || 0) + def.yield;
      if (def.id === 'catnip') game.cats[game.cat].hearts = Math.min(5, game.cats[game.cat].hearts + 1);
      const idx = game.plants.indexOf(p);
      if (idx >= 0) game.plants.splice(idx, 1);
    });
    game.stats.harvests = (game.stats.harvests || 0) + ready.length;
    complete('garden');
    if (game.stats.harvests >= 8) announceAchievement('green-thumb', 'Green Thumb', 'Gathered eight garden harvests');
    const uniq = new Set(game.plants.map(p => plantDef(p).id));
    if (uniq.size >= 6) announceAchievement('botanist', 'Little Botanist', 'Grew six different kinds of plants');
    toast(`Into the basket: ${Object.entries(counts).map(([k, v]) => `${v} ${k}`).join(' · ')} 🧺`);
    closeModal();
    save();
  };
}

function movie() {
  const watched = game.watched || [];
  const body = `<div class="shelf-tabs" id="shelfTabs">
      <button class="active" data-tag="all">All ${GHIBLI.length}</button>
      <button data-tag="cozy">Cozy</button>
      <button data-tag="adventure">Adventure</button>
      <button data-tag="fantasy">Fantasy</button>
      <button data-tag="quiet">Quiet</button>
      <span class="seed-status">${watched.length} watched</span>
    </div>
    <div class="dvd-grid" id="dvdGrid">${GHIBLI.map((m, i) => `<button class="dvd-card ${watched.includes(i) ? 'watched' : ''}" data-film="${i}" data-tag="${m.tag}" style="--a:${m.palette[0]};--b:${m.palette[1]};--c:${m.palette[2]}"><span class="dvd-art"><b>${m.emoji}</b><i>${m.year}</i></span><span class="dvd-copy"><b>${m.title}</b><small>${m.blurb}</small></span></button>`).join('')}</div>
    <div class="modal-note">Every film on this shelf is a Studio Ghibli DVD. Pick one and the inflatable screen will hum to life.</div>`;
  shellModal({
    eyebrow: 'THE DVD SHELF · STUDIO GHIBLI',
    title: 'Choose tonight’s film',
    desc: game.place === 'backyard'
      ? 'Crickets, stars, and the big inflatable screen beside the stone fireplace.'
      : 'The cabin is warm, the screen is huge, and the best cushion is already taken by a cat.',
    body,
    foot: `Watching uses 1 energy · ${watched.length} of ${GHIBLI.length} films watched`,
    wide: true
  });
  const grid = $('#dvdGrid');
  const draw = tag => {
    grid.innerHTML = GHIBLI.map((m, i) => ({ m, i })).filter(({ m }) => tag === 'all' || m.tag === tag).map(({ m, i }) => `<button class="dvd-card ${watched.includes(i) ? 'watched' : ''}" data-film="${i}" data-tag="${m.tag}" style="--a:${m.palette[0]};--b:${m.palette[1]};--c:${m.palette[2]}"><span class="dvd-art"><b>${m.emoji}</b><i>${m.year}</i></span><span class="dvd-copy"><b>${m.title}</b><small>${m.blurb}</small></span></button>`).join('');
    bind();
  };
  const bind = () => {
    $$('#dvdGrid .dvd-card').forEach(btn => {
      btn.onclick = () => watchMovie(+btn.dataset.film);
    });
  };
  $$('#shelfTabs button').forEach(b => {
    b.onclick = () => {
      $$('#shelfTabs button').forEach(x => x.classList.toggle('active', x === b));
      draw(b.dataset.tag);
    };
  });
  bind();
}

function watchMovie(i) {
  const film = GHIBLI[i];
  if (!film) return;
  if (!spend(1)) return;
  const first = !game.watched.includes(i);
  if (first) game.watched.push(i);
  game.movie = i;
  game.stats.movies = (game.stats.movies || 0) + 1;
  game.time = 20;
  game.points += first ? 12 : 7;
  complete('movie');
  if (game.watched.length >= 3) announceAchievement('projectionist', 'Projectionist', 'Watched three Studio Ghibli films');
  if (game.watched.length >= 10) announceAchievement('cinephile', 'Little Cinephile', 'Watched ten Studio Ghibli films');
  const where = game.place === 'backyard' ? 'The backyard screen glows.' : 'The big inflatable screen glows beside the hearth.';
  toast(`Now showing: ${film.title} ${film.emoji} ${where} +${first ? 12 : 7} drops`);
  closeModal();
  save();
}

function openJournal(title = 'A page from your journal') {
  const season = getSeason();
  const watched = (game.watched || []).map(i => GHIBLI[i]?.title).filter(Boolean);
  const recent = watched.slice(-4).reverse();
  const plantTypes = [...new Set(game.plants.map(p => plantDef(p).name))];
  const body = `<div class="journal-grid">
    <div class="journal-card"><span>DAY</span><b>${game.day}</b><small>${season} · ${getWeather()}</small></div>
    <div class="journal-card"><span>GARDEN</span><b>${game.plants.length}/24</b><small>${readyPlants().length} ready · ${plantTypes.length} varieties</small></div>
    <div class="journal-card"><span>FILMS</span><b>${watched.length}/${GHIBLI.length}</b><small>${recent[0] || 'The shelf is waiting'}</small></div>
    <div class="journal-card"><span>COMPANIONS</span><b>${game.cats.length}</b><small>${game.cats.map(c => c.name).join(' · ')}</small></div>
  </div>
  <div class="journal-lists">
    <div><h4>Little things done</h4><p>${game.done.length ? game.tasks.filter(id => game.done.includes(id)).map(id => taskPool.find(t => t.id === id)?.name).join(' · ') : 'The day is still wide open.'}</p></div>
    <div><h4>Keepsakes</h4><p>${game.achievements.length ? game.achievements.join(' · ') : 'Your story is just beginning.'}</p></div>
    <div><h4>In the garden</h4><p>${plantTypes.length ? plantTypes.join(' · ') : 'Nothing planted yet — the seed tins are full of possibility.'}</p></div>
    <div><h4>Recently watched</h4><p>${recent.length ? recent.join(' · ') : 'No film nights yet. The inflatable screen is very patient.'}</p></div>
  </div>`;
  shellModal({
    eyebrow: 'YOUR LITTLE JOURNAL',
    title,
    desc: 'A few things you might like to remember.',
    body,
    foot: 'The quiet days count, too.',
    wide: true
  });
}

/* Mosswood — free-roam controls, interactions & game loop */

const walkBounds = {
  cabin: { minY: 266, maxY: 352 },
  garden: { minY: 162, maxY: 352 },
  woods: { minY: 210, maxY: 352 },
  market: { minY: 246, maxY: 352 },
  backyard: { minY: 266, maxY: 352 }
};
const homePositions = {
  cabin: { x: 200, y: 344 },
  garden: { x: 320, y: 348 },
  woods: { x: 320, y: 344 },
  market: { x: 320, y: 346 },
  backyard: { x: 320, y: 348 }
};
const sceneObjects = {
  cabin: [
    { x: 78, y: 248, name: 'Kitchen stove', run: () => cook() },
    { x: 474, y: 296, name: 'Woodpile', run: () => chop() },
    { x: 340, y: 238, name: 'Inflatable screen', run: () => movie() },
    { x: 426, y: 326, name: 'Your companion', run: () => petAction('pet') },
    { x: 552, y: 298, name: 'Stone hearth', run: () => fire() },
    { x: 300, y: 238, name: 'DVD shelf', run: () => movie() },
    { x: 90, y: 155, name: 'The window', run: () => openJournal('The window') },
    { x: 90, y: 296, name: 'Popcorn cart', run: () => toast('The popcorn cart is warm and ready for the next film. 🍿'), when: () => game.furniture.includes('Popcorn cart') }
  ],
  garden: [
    { x: 250, y: 300, name: 'Garden beds', run: () => gardenMenu() },
    { x: 452, y: 214, name: 'Garden sign', run: () => openJournal('The garden') },
    { x: 554, y: 240, name: 'Greenhouse', run: () => plant() },
    { x: 70, y: 332, name: 'Watering can', run: () => tend() }
  ],
  woods: [
    { x: 196, y: 292, name: 'Berry bush', run: () => forage() },
    { x: 470, y: 300, name: 'Ferny clearing', run: () => explore() },
    { x: 340, y: 332, name: 'Mossy log', run: () => forage() },
    { x: 52, y: 300, name: 'Little stream', run: () => toast('The water is cold, clear, and in no hurry at all.') }
  ],
  market: [
    { x: 196, y: 220, name: 'Market window', run: () => shop('supplies') },
    { x: 449, y: 220, name: 'Homewares window', run: () => shop('home') },
    { x: 510, y: 292, name: 'Plant stand', run: () => shop('plants') },
    { x: 324, y: 244, name: 'Fern & Fable door', run: () => shop('supplies') },
    { x: 150, y: 292, name: 'Produce crates', run: () => shop('supplies') }
  ],
  backyard: [
    { x: 235, y: 220, name: 'Big inflatable screen', run: () => movie() },
    { x: 486, y: 292, name: 'Stone fireplace', run: () => fire() },
    { x: 346, y: 312, name: 'Projector', run: () => movie() },
    { x: 562, y: 320, name: 'Snack crate', run: () => smores() },
    { x: 218, y: 336, name: 'Blanket pile', run: () => movie() }
  ]
};

function playerPosition() {
  if (!game.player[game.place]) game.player[game.place] = { ...homePositions[game.place] };
  return game.player[game.place];
}

function moveTo(x, y, auto = false) {
  const p = playerPosition();
  const b = walkBounds[game.place] || { minY: 20, maxY: 350 };
  p.tx = Math.max(18, Math.min(622, x));
  p.ty = Math.max(b.minY, Math.min(b.maxY, y));
  p.auto = auto;
}

function nearObject() {
  const p = playerPosition();
  const list = (sceneObjects[game.place] || []).filter(o => !o.when || o.when());
  return list.map(o => ({ ...o, d: Math.hypot(o.x - p.x, o.y - p.y) })).sort((a, b) => a.d - b.d)[0];
}

function interact() {
  const o = nearObject();
  if (o && o.d < 62) { o.run(); return; }
  toast('Wander a little closer to a spot that catches your eye.');
}

function tickWalk(dt) {
  const p = playerPosition();
  if (p.tx == null) { p.walking = false; return; }
  const dx = p.tx - p.x, dy = p.ty - p.y;
  const d = Math.hypot(dx, dy);
  const step = Math.min(0.18 * dt, d);
  if (d < 1.5) {
    p.x = p.tx; p.y = p.ty;
    delete p.tx; delete p.ty;
    p.walking = false;
    if (p.auto) { delete p.auto; interact(); }
    save();
    return;
  }
  p.x += dx / d * step;
  p.y += dy / d * step;
  p.walking = true;
  if (Math.abs(dx) > 1) p.face = dx < 0 ? -1 : 1;
}

function act(actionLabel) {
  switch (actionLabel) {
    case 'Cook': return cook();
    case 'Coffee': return drink();
    case 'Chop wood': return chop();
    case 'Movie night': return movie();
    case 'Decorate': return decorate();
    case 'Plant seeds': return plant();
    case 'Harvest': return harvest();
    case 'Tend garden': return tend();
    case 'Forage': return forage();
    case 'Look for cats': return explore();
    case 'Gather wood': return chop();
    case 'Shop supplies': return shop('supplies');
    case 'Shop plants': return shop('plants');
    case 'Shop home': return shop('home');
    case 'Meet cats': return shop('cats');
    case 'Projector night': return movie();
    case 'Light fireplace': return fire();
    case 'Make s’mores': return smores();
    case 'Rest': return rest();
  }
}

/* ----------------------------- inputs ----------------------------- */
$$('.rail-btn[data-place]').forEach(b => b.addEventListener('click', () => go(b.dataset.place)));
$('.brand').addEventListener('click', e => { e.preventDefault(); go('cabin'); });
$('#quickActions').addEventListener('click', e => {
  const b = e.target.closest('[data-action-label]');
  if (b) act(b.dataset.actionLabel);
});
$('.cat-actions').addEventListener('click', e => {
  const b = e.target.closest('[data-action]');
  if (b) petAction(b.dataset.action);
});
$('#taskList').addEventListener('click', e => {
  const t = e.target.closest('[data-task]');
  if (!t) return;
  if (game.done.includes(t.dataset.task)) return toast('Already done, and lovely work!');
  const id = t.dataset.task;
  const actions = {
    breakfast: () => { go('cabin'); cook(); },
    garden: () => { go('garden'); gardenMenu(); },
    woods: () => { go('woods'); forage(); },
    cat: () => petAction('pet'),
    fire: () => { go('cabin'); chop(); },
    drink: () => { go('cabin'); drink(); },
    movie: () => { go('backyard'); movie(); }
  };
  actions[id]?.();
});

canvas.addEventListener('click', e => {
  if ($('#modalRoot').innerHTML) return;
  const r = canvas.getBoundingClientRect();
  const x = (e.clientX - r.left) * W / r.width;
  const y = (e.clientY - r.top) * H / r.height;
  const list = (sceneObjects[game.place] || []).filter(o => !o.when || o.when());
  const near = list.map(o => ({ ...o, d: Math.hypot(o.x - x, o.y - y) })).sort((a, b) => a.d - b.d)[0];
  if (near && near.d < 46) moveTo(near.x, near.y, true);
  else moveTo(x, y, false);
});
canvas.addEventListener('dblclick', () => {
  if (game.energy === 0 && game.place === 'cabin') rest();
});

const moveKeys = {
  ArrowUp: [0, -1], w: [0, -1], W: [0, -1],
  ArrowDown: [0, 1], s: [0, 1], S: [0, 1],
  ArrowLeft: [-1, 0], a: [-1, 0], A: [-1, 0],
  ArrowRight: [1, 0], d: [1, 0], D: [1, 0]
};
document.addEventListener('keydown', e => {
  if ($('#modalRoot').innerHTML) {
    if (e.key === 'Escape') closeModal();
    return;
  }
  if (e.key === 'Escape') { closeModal(); return; }
  if (moveKeys[e.key]) {
    e.preventDefault();
    const p = playerPosition();
    const v = moveKeys[e.key];
    const nx = Math.max(18, Math.min(622, (p.tx ?? p.x) + v[0] * 38));
    const b = walkBounds[game.place] || { minY: 20, maxY: 350 };
    const ny = Math.max(b.minY, Math.min(b.maxY, (p.ty ?? p.y) + v[1] * 38));
    p.tx = nx; p.ty = ny; p.auto = false;
  } else if (e.key.toLowerCase() === 'e') {
    e.preventDefault();
    interact();
  } else if (e.key.toLowerCase() === 'r' && game.energy === 0 && game.place === 'cabin') {
    rest();
  }
});

function addTouchPad() {
  const wrap = $('.scene-wrap');
  if (!wrap || $('#walkPad')) return;
  const pad = document.createElement('div');
  pad.id = 'walkPad';
  pad.className = 'walk-pad';
  pad.setAttribute('aria-label', 'Movement controls');
  [['↑', 0, -1], ['←', -1, 0], ['↓', 0, 1], ['→', 1, 0]].forEach(([txt, dx, dy]) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = txt;
    b.setAttribute('aria-label', `Walk ${txt}`);
    b.onclick = () => {
      const p = playerPosition();
      const bnd = walkBounds[game.place] || { minY: 20, maxY: 350 };
      p.tx = Math.max(18, Math.min(622, p.x + dx * 54));
      p.ty = Math.max(bnd.minY, Math.min(bnd.maxY, p.y + dy * 54));
      p.auto = false;
    };
    pad.append(b);
  });
  const use = document.createElement('button');
  use.className = 'walk-use';
  use.textContent = 'E';
  use.title = 'Interact nearby';
  use.onclick = interact;
  pad.append(use);
  wrap.append(pad);
}

/* ----------------------------- side panel & menus ----------------------------- */
$('#activityBtn').onclick = () => {
  if (game.place === 'cabin') { if (movieDef()) movie(); else cook(); }
  else if (game.place === 'garden') plant();
  else if (game.place === 'woods') forage();
  else if (game.place === 'market') shop('supplies');
  else movie();
};
$('#catMore').onclick = () => {
  const cat = game.cats[game.cat];
  openModal('A little about ' + cat.name, `${cat.name} has been with you for ${cat.hearts + 1} lovely moments. Their trust grows with every meal, game, and gentle hello.`, [
    { emoji: '♡', name: 'Give a gentle cuddle', desc: 'A soft, no-pressure hello.', run: () => { closeModal(); petAction('pet'); } },
    {
      emoji: '📖', name: 'Meet your other companions', desc: game.cats.length > 1 ? game.cats.map(c => c.name).join(' · ') : 'There may be a new friend out in the woods.',
      run: () => {
        closeModal();
        if (game.cats.length > 1) {
          openModal('Your little companions', 'Choose who to spend a little time with.', game.cats.map((c, i) => ({
            emoji: c.emoji, name: c.name, desc: c.mood, cost: i === game.cat ? 'WITH YOU NOW' : 'Come say hello',
            run: () => { game.cat = i; closeModal(); save(); toast(`${c.name} trots over to say hello ♡`); }
          })));
        } else go('woods');
      }
    }
  ]);
};
$('#helpBtn').onclick = () => openModal('Welcome to Mosswood', 'A tiny woodland life, at your own pace. There is no way to lose, and no wrong way to spend a day.', [
  { emoji: '⌂', name: 'Explore your little world', desc: 'Visit the cabin, garden, woods, market, and the backyard picture show.', run: () => closeModal() },
  { emoji: '🌱', name: 'Grow 23 kinds of plants', desc: 'Herbs, veggies, and fruit. Plant with seeds, harvest when ready.', run: () => { closeModal(); go('garden'); plant(); } },
  { emoji: '🎬', name: 'Have a Studio Ghibli night', desc: 'The DVD shelf has 25 films. The screen is already inflated.', run: () => { closeModal(); go('cabin'); movie(); } },
  { emoji: '✦', name: 'Earn dew drops', desc: 'Complete the three little daily tasks for points.', run: () => closeModal() },
  { emoji: '☾', name: 'Rest when you need to', desc: 'When the day is done, rest at home to begin a fresh morning.', run: () => { closeModal(); rest(); } }
], 'Your game saves automatically in this browser.');
$('#soundBtn').onclick = () => toast('The woods are quiet today. Imagine the birdsong and the projector’s soft hum ♫');
$('#journalBtn').onclick = () => openJournal();
$('#resetBtn').onclick = () => openModal('A fresh start?', 'This will begin a new little save. Your cabin will be waiting just the same.', [{
  emoji: '🌱', name: 'Start a new save', desc: 'Your current progress will be cleared from this browser.',
  run: () => {
    localStorage.removeItem('mosswood-save');
    game = { ...initial, inventory: { ...initial.inventory }, cats: [...initial.cats], tasks: pickTasks(), done: [], unlocks: ['backyard'], furniture: [], watched: [], movie: null, player: {}, stats: { recipes: 0, drinks: 0, harvests: 0, movies: 0 } };
    closeModal();
    save();
    toast('A new beginning, and a lovely one at that.');
  }
}]);

/* ----------------------------- game loop ----------------------------- */
let lastFrame = performance.now();
function frame(now) {
  const dt = Math.min(60, now - lastFrame);
  lastFrame = now;
  tickWalk(dt);
  drawScene(now / 1000);
  requestAnimationFrame(frame);
}

function boot() {
  Object.keys(homePositions).forEach(place => {
    if (!game.player[place]) game.player[place] = { ...homePositions[place] };
  });
  addTouchPad();
  renderUI();
  requestAnimationFrame(frame);
}

window.__mosswood = {
  get game() { return game; },
  go, movie, plant, harvest, rest, save, moveTo, drawScene, act,
  GHIBLI, PLANTS
};

boot();

