.seed-card:hover{background:#f3f5ea;border-color:#cfdbc2;transform:translateY(-1px)}
.seed-card:disabled{opacity:.5;cursor:default;transform:none}
.seed-art{width:40px;height:43px;flex:none;border-radius:6px;background:linear-gradient(160deg,var(--leaf2),var(--leaf));position:relative;display:grid;place-items:center;overflow:hidden}
.seed-art b{font-size:19px;z-index:2;filter:drop-shadow(0 1px 1px #0004)}
