.harvest-list+.ritual-button{width:100%}
.journal-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.journal-card{background:#f3f4e8;border:1px solid #e9ebdd;border-radius:8px;padding:10px 11px}
.journal-card span{font:8px var(--pixel);letter-spacing:.7px;color:#a0a795;display:block}
.journal-card b{font-size:21px;display:block;margin-top:2px;color:#536b58}
.journal-card small{font-size:9px;color:#929d8c;display:block;margin-top:2px;line-height:1.3}
.journal-lists{display:grid;grid-template-columns:1fr 1fr;gap:9px 16px;margin-top:14px}
.journal-lists h4{font-size:10px;margin:0 0 3px;color:#65785f}
.journal-lists p{font-size:10px;line-height:1.45;color:#929b8d;margin:0}
@media(max-width:700px){.modal.wide{width:100%}.journal-grid{grid-template-columns:1fr 1fr}.journal-lists{grid-template-columns:1fr}.dvd-grid,.seed-grid{grid-template-columns:1fr 1fr}.seed-status{width:100%;margin:2px 0 0}.dvd-card{padding:6px}.dvd-copy small{display:none}.seed-copy em{display:none}}
@media(max-width:470px){.dvd-grid,.seed-grid{grid-template-columns:1fr}.dvd-copy small{display:block}}
